import{_ as o,o as t,c as n,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-Elementwise-Functions.md","filePath":"manual-en/Matrix-Elementwise-Functions.md","lastUpdated":1785684581000}'),a={name:"manual-en/Matrix-Elementwise-Functions.md"};function i(s,e,c,p,d,m){return t(),n("div",null,[...e[0]||(e[0]=[r('<h4 id="_16-4-2-1-elementwise-functions" tabindex="-1">16.4.2.1 Elementwise Functions <a class="header-anchor" href="#_16-4-2-1-elementwise-functions" aria-label="Permalink to &quot;16.4.2.1 Elementwise Functions&quot;">​</a></h4><p>These functions act on each element of their argument independently, like the elementwise operators (see <a href="./Matrix-Elementwise-Binary-Operators">Matrix Elementwise Binary Operators</a>).</p><p>Matrix Function: <strong>ABS</strong> <em>( M)</em></p><p>Takes the absolute value of each element of M.</p><p><code>ABS({-1, 2; -3, 0}) ⇒ {1, 2; 3, 0}</code></p><p>Matrix Function: <strong>ARSIN</strong> <em>( M)</em> Matrix Function: <strong>ARTAN</strong> <em>( M)</em></p><p>Computes the inverse sine or tangent, respectively, of each element in M. The results are in radians, between <em>-\\pi/2</em> and <em>+\\pi/2</em> , inclusive.</p><p>The value of <em>\\pi</em> can be computed as <code>4*ARTAN(1)</code>.</p><p><code>ARSIN({-1, 0, 1}) ⇒ {-1.57, 0, 1.57}</code> (approximately)</p><p><code>ARTAN({-5, -1, 1, 5}) ⇒ {-1.37, -.79, .79, 1.37}</code> (approximately)</p><p>Matrix Function: <strong>COS</strong> <em>( M)</em> Matrix Function: <strong>SIN</strong> <em>( M)</em></p><p>Computes the cosine or sine, respectively, of each element in M, which must be in radians.</p><p><code>COS({0.785, 1.57; 3.14, 1.57 + 3.14}) ⇒ {.71, 0; -1, 0}</code> (approximately)</p><p>Matrix Function: <strong>EXP</strong> <em>( M)</em></p><p>Computes <em>e^x</em> for each element x in M.</p><p><code>EXP({2, 3; 4, 5}) ⇒ {7.39, 20.09; 54.6, 148.4}</code> (approximately)</p><p>Matrix Function: <strong>LG10</strong> <em>( M)</em> Matrix Function: <strong>LN</strong> <em>( M)</em></p><p>Takes the logarithm with base 10 or base <em>e</em> , respectively, of each element in M.</p><p><code>LG10({1, 10, 100, 1000}) ⇒ {0, 1, 2, 3}</code><br><code>LG10(0) ⇒</code> (error)</p><p><code>LN({EXP(1), 1, 2, 3, 4}) ⇒ {1, 0, .69, 1.1, 1.39}</code> (approximately)<br><code>LN(0) ⇒</code> (error)</p><p>Matrix Function: <strong>MOD</strong> <em>( M, s)</em></p><p>Takes each element in M modulo nonzero scalar value s, that is, the remainder of division by s. The sign of the result is the same as the sign of the dividend.</p><p><code>MOD({5, 4, 3, 2, 1, 0}, 3) ⇒ {2, 1, 0, 2, 1, 0}</code><br><code>MOD({5, 4, 3, 2, 1, 0}, -3) ⇒ {2, 1, 0, 2, 1, 0}</code><br><code>MOD({-5, -4, -3, -2, -1, 0}, 3) ⇒ {-2, -1, 0, -2, -1, 0}</code><br><code>MOD({-5, -4, -3, -2, -1, 0}, -3) ⇒ {-2, -1, 0, -2, -1, 0}</code><br><code>MOD({5, 4, 3, 2, 1, 0}, 1.5) ⇒ {.5, 1.0, .0, .5, 1.0, .0}</code><br><code>MOD({5, 4, 3, 2, 1, 0}, 0) ⇒</code> (error)</p><p>Matrix Function: <strong>RND</strong> <em>( M)</em> Matrix Function: <strong>TRUNC</strong> <em>( M)</em></p><p>Rounds each element of M to an integer. <code>RND</code> rounds to the nearest integer, with halves rounded to even integers, and <code>TRUNC</code> rounds toward zero.</p><p><code>RND({-1.6, -1.5, -1.4}) ⇒ {-2, -2, -1}</code><br><code>RND({-.6, -.5, -.4}) ⇒ {-1, 0, 0}</code><br><code>RND({.4, .5, .6} ⇒ {0, 0, 1}</code><br><code>RND({1.4, 1.5, 1.6}) ⇒ {1, 2, 2}</code></p><p><code>TRUNC({-1.6, -1.5, -1.4}) ⇒ {-1, -1, -1}</code><br><code>TRUNC({-.6, -.5, -.4}) ⇒ {0, 0, 0}</code><br><code>TRUNC({.4, .5, .6} ⇒ {0, 0, 0}</code><br><code>TRUNC({1.4, 1.5, 1.6}) ⇒ {1, 1, 1}</code></p><p>Matrix Function: <strong>SQRT</strong> <em>( M)</em></p><p>Takes the square root of each element of M, which must not be negative.</p><p><code>SQRT({0, 1, 2, 4, 9, 81}) ⇒ {0, 1, 1.41, 2, 3, 9}</code> (approximately)<br><code>SQRT(-1) ⇒</code> (error)</p>',30)])])}const M=o(a,[["render",i]]);export{u as __pageData,M as default};
